// Gambar (urut shot) + cerita -> request Claude untuk prompt Google Flow (Veo).
const item = $input.first();
const keys = Object.keys(item.binary || {}).sort((a, b) => Number(a.split('_').pop()) - Number(b.split('_').pop()));
if (!keys.length) throw new Error('Tidak ada gambar.');
const content = [];
for (const [i, k] of keys.entries()) {
  const buf = await this.helpers.getBinaryDataBuffer(0, k);
  content.push({ type: 'text', text: `Gambar shot ${i + 1}:` });
  content.push({ type: 'image', source: { type: 'base64', media_type: item.binary[k].mimeType || 'image/png', data: buf.toString('base64') } });
}
content.push({ type: 'text', text: `Alur cerita:\n${item.json['Cerita']}` });
const system = `Kamu sutradara iklan video pendek yang ahli menulis prompt Google Veo (Google Flow, mode Ingredients to Video).
Semua gambar (${keys.length}) diupload sekaligus sebagai ingredients untuk SATU klip 8 detik. Gambar ke-N = adegan ke-N sesuai urutan.
Tulis SATU prompt bahasa Inggris (120-200 kata) yang menggabungkan semua adegan berurutan dengan timestamp, contoh:
"[0-4s] Handheld close-up ... (match image 1 exactly) ... [4-8s] Hard cut to ... (match image 2 exactly) ..."
Aturan:
- Bagi 8 detik sesuai durasi di cerita; jika total cerita > 8 detik, padatkan proporsional.
- Tiap adegan: jenis shot & gerakan kamera, aksi subjek, sebut "matching image N" agar lokasi/warna/benda identik dengan gambar.
- Jangan tambah orang/benda baru. Satu gaya cahaya & color grading untuk seluruh klip.
- Ikuti instruksi cerita soal suara. Jika tanpa voice over: "No dialogue, no voice-over, no music; only natural ambient sound."
- Akhiri dengan: "Photorealistic, 9:16 vertical, no text, no subtitles, no morphing between scenes."
Balas HANYA JSON: {"judul":"<ringkas, Indonesia>","prompt":"...","catatan":"<tips singkat Indonesia>"}`;
return [{ json: { body: { model: 'claude-sonnet-5-5', max_tokens: 3000, system, messages: [{ role: 'user', content }] } } }];

// Satu pesan berisi satu prompt gabungan.
const text = $input.first().json.content[0].text;
const p = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
const n = $('Siapkan Prompt').first().json.body.messages[0].content.filter(c => c.type === 'image').length;
return [{ json: {
  text: `🎬 ${p.judul}\nGoogle Flow → Ingredients to Video → upload ${n} gambar (urut) → tempel prompt:\n${p.catatan ? '📝 ' + p.catatan + '\n' : ''}\n${p.prompt}`,
} }];
